dataset_id &lt;- "bb7c6f27-8efe-4bec-977f-a9c353574771"
api_url &lt;- paste0(
  "https://api.obis.org/v3/occurrence?datasetid=",
  dataset_id,
  "&size=10000"
)

obis_data &lt;- jsonlite::fromJSON(
  paste(readLines(api_url, warn = FALSE), collapse = "\n"),
  simplifyVector = FALSE
)

if (is.null(obis_data$total) || is.null(obis_data$results)) {
  stop("OBIS did not return the expected occurrence records.")
}
if (length(obis_data$results) != as.integer(obis_data$total)) {
  stop("OBIS returned an incomplete set of occurrence records.")
}

if (any(purrr::map_chr(
  obis_data$results,
  \(record) record$dataset_id
) != dataset_id)) {
  stop("OBIS returned records from an unexpected dataset.")
}

sightings &lt;- purrr::map_dfr(obis_data$results, \(record) {
  if (is.null(record$eventDate) ||
      is.null(record$individualCount)) {
    stop("An OBIS record is missing its date or estimated dolphin count.")
  }

  tibble(
    sighting_date = as.POSIXct(
      record$eventDate,
      format = "%Y-%m-%dT%H:%M:%OS",
      tz = "UTC"
    ),
    dolphins = as.integer(record$individualCount)
  )
})

if (anyNA(sightings)) {
  stop("An OBIS sighting has an invalid date or dolphin count.")
}

sightings &lt;- sightings |&gt;
  mutate(
    sighting_year = as.integer(format(sighting_date, "%Y")),
    month = factor(
      format(sighting_date, "%b"),
      levels = month.abb
    )
  )

The plot includes 6,391 sightings and 30,980 counted dolphins from 1971 to 2009.

dolphin_dots &lt;- sightings |&gt;
  tidyr::uncount(dolphins, .id = "dolphin_in_sighting", .remove = FALSE)

ggplot(
  dolphin_dots,
  aes(x = month, y = dolphins, color = sighting_year)
) +
  geom_point(
    position = position_jitter(width = 0.18, height = 0, seed = 1),
    alpha = 0.4,
    size = 0.8
  ) +
  scale_color_viridis_c(name = "Sighting year", breaks = seq(1971, 2009, by = 5)) +
  labs(
    title = "Dolphin group size by month and year",
    x = "Month",
    y = "Estimated dolphins in the sighting",
    caption = "One dot = one dolphin counted | OBIS/SDRP | CC BY-NC 4.0."
  ) +
  theme_minimal()








Source: Wells, R., R. Tyson, and J. Allen. 2017. Sarasota Dolphin Research Program Bottlenose Sightings 1971–2009. Version 1.0.0. Dataset published in OBIS-SEAMAP. https://doi.org/10.82144/cfb9c450. Licensed CC BY-NC 4.0.
